10	/**
11	 * POST /api/invoices/{invoiceId}/lineitems — add a line item (description, quantity, unit price) to
12	 * an existing invoice, then re-total the invoice from its line items and echo back the saved line.
13	 * A missing/blank description, a non-positive quantity or a negative unit price, or an unknown
14	 * invoice, is rejected with 400 and nothing is written.
15	 */
16	public class CreateLineItemLogic {
17	
18	    public void service(@HttpPathParameter("invoiceId") String invoiceId,
19	            @RequestBody NewLineItem newLineItem, InvoiceRepository invoices,
20	            LineItemRepository lineItems, ObjectResponse<LineItemView> response) {
21	        Long id = Long.valueOf(invoiceId);
22	        Invoice invoice = invoices.findById(id).orElseThrow(
23	                () -> new HttpException(HttpStatus.BAD_REQUEST, "An existing invoice is required"));
24	        String description = newLineItem.getDescription();
25	        if (description == null || description.isBlank()) {
26	            throw new HttpException(HttpStatus.BAD_REQUEST, "A description is required");
27	        }
28	        Integer quantity = newLineItem.getQuantity();
29	        if (quantity == null || quantity <= 0) {
30	            throw new HttpException(HttpStatus.BAD_REQUEST, "A quantity greater than zero is required");
31	        }
32	        BigDecimal unitPrice = newLineItem.getUnitPrice();
33	        if (unitPrice == null || unitPrice.compareTo(BigDecimal.ZERO) < 0) {
34	            throw new HttpException(HttpStatus.BAD_REQUEST, "A unit price of zero or more is required");
35	        }
36	        LineItem saved = lineItems.save(new LineItem(id, description.trim(), quantity, unitPrice));
37	
38	        // Keep the invoice's amount in step with its line items: the total the owner is charging.
39	        BigDecimal amount = lineItems.findByInvoiceIdOrderByIdAsc(id).stream()
40	                .map(LineItem::lineTotal)
41	                .reduce(BigDecimal.ZERO, BigDecimal::add);
42	        invoice.setAmount(amount);
43	        invoices.save(invoice);
44	
45	        response.send(new LineItemView(saved.getId(), saved.getInvoiceId(), saved.getDescription(),
46	                saved.getQuantity(), saved.getUnitPrice()));
47	    }
48	}
